import argparse
from typing import Any

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel, Field

from app.rules import order_rules
from app.store import orders, payment_imports, settlements
from app.store.db import connect, migrate

app = FastAPI(title="settlement-ledger")

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

class ReversalIn(BaseModel):
    reversal_id: str = Field(min_length=1)
    payment_id: str = Field(min_length=1)

class SettlementIn(BaseModel):
    settlement_id: str = Field(min_length=1)

class SettlementRevocationIn(BaseModel):
    revocation_id: str = Field(min_length=1)

class PaymentImportLineIn(BaseModel):
    # 行内字段保持宽容：金额非法等业务问题按行拒绝，而不是让整批 422
    line_seq: int
    order_id: str
    amount_cents: Any

class PaymentImportIn(BaseModel):
    batch_id: str = Field(min_length=1)
    lines: list[PaymentImportLineIn] = Field(min_length=1)

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn) -> dict:
    order_rules.assert_currency(body.currency)
    try:
        orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            raise HTTPException(status_code=409, detail="order already accepted")
        raise
    return orders.get(body.tenant, body.order_id)

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="", alias=None)) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(order_id: str, body: PaymentIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        order = orders.add_payment(x_tenant, order_id, body.amount_cents)
    except orders.PaymentExceedsOutstanding as error:
        raise HTTPException(status_code=409, detail=str(error))
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/reversals")
def reverse_payment(order_id: str, body: ReversalIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        result = orders.reverse_payment(x_tenant, order_id, body.reversal_id, body.payment_id)
    except orders.PaymentNotFound:
        # 收款不存在（含跨租户点名）一律按不存在处理，不泄漏对象是否存在
        raise HTTPException(status_code=404, detail="payment not found")
    except orders.PaymentAlreadyReversed as error:
        raise HTTPException(status_code=409, detail=str(error))
    except orders.ReversalConflict as error:
        raise HTTPException(status_code=409, detail=str(error))
    except orders.ReversalBlockedBySettlement as error:
        raise HTTPException(status_code=409, detail=str(error))
    if result is None:
        raise HTTPException(status_code=404, detail="order not found")
    return result

@app.post("/orders/{order_id}/settlements", status_code=201)
def settle_order(order_id: str, body: SettlementIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        view, _created = settlements.settle(x_tenant, order_id, body.settlement_id)
    except settlements.SettlementNotFound as error:
        # 订单不存在/跨租户点名统一按不存在处理
        raise HTTPException(status_code=404, detail=str(error))
    except settlements.OrderNotFullyPaid as error:
        raise HTTPException(status_code=409, detail=str(error))
    except settlements.SettlementNotBalanced as error:
        raise HTTPException(status_code=409, detail=str(error))
    except settlements.SettlementAlreadyActive as error:
        raise HTTPException(status_code=409, detail=str(error))
    except settlements.SettlementKeyConflict as error:
        raise HTTPException(status_code=409, detail=str(error))
    return _settlement_response(view)

@app.post("/settlements/{settlement_doc_id}/revocations")
def revoke_settlement(settlement_doc_id: str, body: SettlementRevocationIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        view = settlements.revoke(x_tenant, settlement_doc_id, body.revocation_id)
    except settlements.SettlementNotFound:
        # 结算单不存在（含跨租户点名、撤销不存在的结算单）按不存在处理
        raise HTTPException(status_code=404, detail="settlement not found")
    except settlements.SettlementAlreadyRevoked as error:
        raise HTTPException(status_code=409, detail=str(error))
    except settlements.RevocationConflict as error:
        raise HTTPException(status_code=409, detail=str(error))
    return _settlement_response(view)

def _settlement_response(view: dict) -> dict:
    # 对外字段：settlement_id 为调用方指定的结算标识（原样回显），
    # settlement_doc_id 为服务端分配的结算单单据标识（撤销时点名使用）
    return {
        "settlement_doc_id": view["settlement_id"],
        "settlement_id": view["settlement_key"],
        "order_id": view["order_id"],
        "tenant": view["tenant"],
        "amount_cents": view["amount_cents"],
        "status": view["status"],
        "created_at": view["created_at"],
        "revoked_at": view["revoked_at"],
        **({"revocation_id": view["revocation_id"]} if "revocation_id" in view else {}),
    }

@app.post("/payment-imports")
def import_payments(body: PaymentImportIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    lines = [
        payment_imports.ImportLine(
            line_no=line_no,
            line_seq=item.line_seq,
            order_id=item.order_id,
            amount_cents=item.amount_cents,
        )
        for line_no, item in enumerate(body.lines, start=1)
    ]
    # 逐行独立事务：业务拒绝落到逐行结果；内部错误时出错行整笔回滚并以 5xx 返回，
    # 此前已提交的行保持生效，调用方用同一批次标识续跑即可补齐剩余行
    return payment_imports.submit(x_tenant, body.batch_id, lines)

@app.get("/payment-imports/{batch_id}")
def read_payment_import(batch_id: str, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    batch = payment_imports.get_batch(x_tenant, batch_id)
    if batch is None:
        raise HTTPException(status_code=404, detail="import batch not found")
    return batch

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

"""结算单的发起（对账核销）与撤销。

发起结算在单事务内完成「结算标识幂等判定 + 订单存在性 + 未收满判定 +
未冲正收款合计闭合核对 + 结算单落库」，任一条不满足整笔回滚，不留下半笔生效的核销。
撤销在单事务内解除该结算单的核销状态，不触碰订单收款与已收金额。
所有写事务均以 BEGIN IMMEDIATE 串行化，与登记收款/冲正互斥，闭合关系始终成立。
"""
import sqlite3
from uuid import uuid4

from app.store.db import connect

ACTIVE = "active"
REVOKED = "revoked"


class OrderNotFullyPaid(Exception):
    """订单未收满（账面已收金额不等于订单金额），不能发起结算。"""


class SettlementNotBalanced(Exception):
    """对账不闭合：未冲正收款合计、账面已收金额与订单金额三者不一致。"""


class SettlementAlreadyActive(Exception):
    """同一订单已存在未撤销的结算单。"""


class SettlementKeyConflict(Exception):
    """同一结算标识已被用于另一订单。"""


class SettlementNotFound(Exception):
    """结算单不存在（含跨租户点名，统一按不存在处理）。"""


class SettlementAlreadyRevoked(Exception):
    """结算单此前已被撤销。"""


class RevocationConflict(Exception):
    """撤销标识已被用于另一张结算单。"""


def settle(tenant: str, order_id: str, settlement_key: str) -> tuple[dict, bool]:
    """按订单发起结算，返回（结算单视图, 是否首次生成）。失败抛出业务异常，状态不变。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        keyed = conn.execute(
            "SELECT settlement_id, order_id, status FROM settlements WHERE tenant=? AND settlement_key=?",
            (tenant, settlement_key),
        ).fetchone()
        if keyed is not None:
            # 同一结算标识：指向同一订单为幂等重放，返回首次生成的同一张结算单（含其当前状态）；
            # 指向另一订单为冲突，既有状态保持不变
            conn.execute("ROLLBACK")
            if keyed["order_id"] != order_id:
                raise SettlementKeyConflict("settlement id already used for another order")
            return _settlement_view(tenant, keyed["settlement_id"]), False

        order = conn.execute(
            "SELECT amount_cents, paid_cents, status FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if order is None:
            # 订单不存在或跨租户点名统一按不存在处理，不泄漏对象是否存在
            conn.execute("ROLLBACK")
            raise SettlementNotFound("order not found")

        active = conn.execute(
            "SELECT settlement_id FROM settlements WHERE tenant=? AND order_id=? AND status='active'",
            (tenant, order_id),
        ).fetchone()
        if active is not None:
            conn.execute("ROLLBACK")
            raise SettlementAlreadyActive("active settlement already exists for order")

        # 对账核销只认真实的未被冲正收款合计，不信任订单状态字段
        live_total = conn.execute(
            "SELECT COALESCE(SUM(p.amount_cents),0) AS s FROM payments p "
            "WHERE p.tenant=? AND p.order_id=? AND NOT EXISTS ("
            "SELECT 1 FROM reversals v WHERE v.tenant=p.tenant AND v.order_id=p.order_id "
            "AND v.payment_id=p.payment_id)",
            (tenant, order_id),
        ).fetchone()["s"]

        if order["paid_cents"] != order["amount_cents"] or live_total != order["amount_cents"]:
            # 未收满与对账不闭合分别以可区分的原因拒绝：前者是钱没收齐，后者是账面/明细对不上
            conn.execute("ROLLBACK")
            if live_total != order["paid_cents"]:
                raise SettlementNotBalanced("reconciled payments do not match booked amount")
            raise OrderNotFullyPaid("order not fully paid")

        settlement_id = uuid4().hex
        try:
            conn.execute(
                "INSERT INTO settlements(tenant, settlement_id, settlement_key, order_id, amount_cents, status) "
                "VALUES(?,?,?,?,?,'active')",
                (tenant, settlement_id, settlement_key, order_id, live_total),
            )
            conn.execute("COMMIT")
        except sqlite3.IntegrityError:
            # 并发兜底：结算标识被占用或该订单已有未撤销结算单，整笔回滚后按可区分原因拒绝
            conn.execute("ROLLBACK")
            clash = connect()
            try:
                same_key = clash.execute(
                    "SELECT settlement_id, order_id FROM settlements WHERE tenant=? AND settlement_key=?",
                    (tenant, settlement_key),
                ).fetchone()
            finally:
                clash.close()
            if same_key is not None:
                if same_key["order_id"] == order_id:
                    # 并发下同标识同订单已落库：按幂等重放返回同一张结算单
                    return _settlement_view(tenant, same_key["settlement_id"]), False
                raise SettlementKeyConflict("settlement id already used for another order")
            raise SettlementAlreadyActive("active settlement already exists for order")
    finally:
        conn.close()
    return _settlement_view(tenant, settlement_id), True


def revoke(tenant: str, settlement_id: str, revocation_id: str) -> dict:
    """撤销结算单：只解除核销状态，不改变订单收款与已收金额。失败抛出业务异常。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        keyed = conn.execute(
            "SELECT settlement_id FROM settlement_revocations WHERE tenant=? AND revocation_id=?",
            (tenant, revocation_id),
        ).fetchone()
        if keyed is not None:
            # 同一撤销标识：指向同一结算单为幂等重放；指向另一结算单为冲突
            conn.execute("ROLLBACK")
            if keyed["settlement_id"] != settlement_id:
                raise RevocationConflict("revocation id already used for another settlement")
            return _revocation_view(tenant, settlement_id, revocation_id)

        settlement = conn.execute(
            "SELECT status FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
        if settlement is None:
            # 结算单不存在或跨租户点名统一按不存在处理
            conn.execute("ROLLBACK")
            raise SettlementNotFound("settlement not found")
        if settlement["status"] == REVOKED:
            conn.execute("ROLLBACK")
            raise SettlementAlreadyRevoked("settlement already revoked")

        try:
            conn.execute(
                "INSERT INTO settlement_revocations(tenant, revocation_id, settlement_id) VALUES(?,?,?)",
                (tenant, revocation_id, settlement_id),
            )
            conn.execute(
                "UPDATE settlements SET status='revoked', "
                "revoked_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') "
                "WHERE tenant=? AND settlement_id=?",
                (tenant, settlement_id),
            )
            conn.execute("COMMIT")
        except sqlite3.IntegrityError:
            # 并发兜底：撤销标识被占用或结算单已被撤销，整笔回滚后按可区分原因拒绝
            conn.execute("ROLLBACK")
            clash = connect()
            try:
                same_id = clash.execute(
                    "SELECT settlement_id FROM settlement_revocations WHERE tenant=? AND revocation_id=?",
                    (tenant, revocation_id),
                ).fetchone()
            finally:
                clash.close()
            if same_id is not None:
                if same_id["settlement_id"] == settlement_id:
                    # 并发下同标识同结算单已落库：按幂等重放返回首次结果
                    return _revocation_view(tenant, settlement_id, revocation_id)
                raise RevocationConflict("revocation id already used for another settlement")
            raise SettlementAlreadyRevoked("settlement already revoked")
    finally:
        conn.close()
    return _revocation_view(tenant, settlement_id, revocation_id)


def get(tenant: str, settlement_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, settlement_id, settlement_key, order_id, amount_cents, status, created_at, revoked_at "
            "FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
    finally:
        conn.close()
    if row is None:
        return None
    return dict(row)


def _settlement_view(tenant: str, settlement_id: str) -> dict:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, settlement_id, settlement_key, order_id, amount_cents, status, created_at, revoked_at "
            "FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
    finally:
        conn.close()
    return dict(row)


def _revocation_view(tenant: str, settlement_id: str, revocation_id: str) -> dict:
    return {
        **_settlement_view(tenant, settlement_id),
        "revocation_id": revocation_id,
    }

import sqlite3
import uuid

from app.store.db import connect


class PaymentExceedsOutstanding(ValueError):
    """收款金额超过订单未收金额。"""

class PaymentNotFound(Exception):
    """订单内不存在该收款标识（跨租户访问同样按此处理）。"""

class PaymentAlreadyReversed(Exception):
    """该收款此前已被冲正。"""

class ReversalConflict(Exception):
    """冲正标识已被用于冲正另一笔收款。"""

class ReversalBlockedBySettlement(Exception):
    """订单存在未撤销的结算单，核销闭合期间不允许冲正收款。"""

def insert(tenant: str, order_id: str, amount_cents: int, currency: str) -> None:
    conn = connect()
    try:
        conn.execute(
            "INSERT INTO orders(tenant, order_id, amount_cents, paid_cents, currency, status) VALUES(?,?,?,0,?,'accepted')",
            (tenant, order_id, amount_cents, currency),
        )
    finally:
        conn.close()

def get(tenant: str, order_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, order_id, amount_cents, paid_cents, currency, status FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
    finally:
        conn.close()
    if row is None:
        return None
    return _order_view(row)

def _order_view(row: sqlite3.Row) -> dict:
    return {**dict(row), "outstanding_cents": row["amount_cents"] - row["paid_cents"]}

def add_payment(tenant: str, order_id: str, amount_cents: int) -> dict | None:
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        if amount_cents <= 0 or row["paid_cents"] + amount_cents > row["amount_cents"]:
            conn.execute("ROLLBACK")
            raise PaymentExceedsOutstanding("payment exceeds outstanding amount")
        payment_id = uuid.uuid4().hex
        conn.execute(
            "INSERT INTO payments(tenant, order_id, payment_id, amount_cents) VALUES(?,?,?,?)",
            (tenant, order_id, payment_id, amount_cents),
        )
        conn.execute(
            "UPDATE orders SET paid_cents = paid_cents + ?, status = CASE WHEN paid_cents + ? >= amount_cents THEN 'settled' ELSE 'accepted' END WHERE tenant=? AND order_id=?",
            (amount_cents, amount_cents, tenant, order_id),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    view = get(tenant, order_id)
    view["payment_id"] = payment_id
    return view

def reverse_payment(tenant: str, order_id: str, reversal_id: str, payment_id: str) -> dict | None:
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        order = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if order is None:
            conn.execute("ROLLBACK")
            return None

        blocked = conn.execute(
            "SELECT 1 FROM settlements WHERE tenant=? AND order_id=? AND status='active'",
            (tenant, order_id),
        ).fetchone()
        if blocked is not None:
            # 核销闭合期间（存在未撤销结算单）不允许冲正收款，否则结算金额快照与未冲正收款合计会脱节；
            # 需先撤销结算再冲正。状态保持不变
            conn.execute("ROLLBACK")
            raise ReversalBlockedBySettlement("payment reversal blocked by active settlement")

        existing = conn.execute(
            "SELECT reversal_id, payment_id, amount_cents FROM reversals WHERE tenant=? AND order_id=? AND reversal_id=?",
            (tenant, order_id, reversal_id),
        ).fetchone()
        if existing is not None:
            # 幂等重放：同一冲正标识只能指向同一笔收款，重复请求返回首次结果
            if existing["payment_id"] != payment_id:
                conn.execute("ROLLBACK")
                raise ReversalConflict("reversal id already used for another payment")
            conn.execute("COMMIT")
            return _reversal_view(tenant, order_id, existing)

        payment = conn.execute(
            "SELECT amount_cents FROM payments WHERE tenant=? AND order_id=? AND payment_id=?",
            (tenant, order_id, payment_id),
        ).fetchone()
        if payment is None:
            conn.execute("ROLLBACK")
            raise PaymentNotFound("payment not found")

        reversed_row = conn.execute(
            "SELECT 1 FROM reversals WHERE tenant=? AND order_id=? AND payment_id=?",
            (tenant, order_id, payment_id),
        ).fetchone()
        if reversed_row is not None:
            conn.execute("ROLLBACK")
            raise PaymentAlreadyReversed("payment already reversed")

        amount_cents = payment["amount_cents"]
        try:
            conn.execute(
                "INSERT INTO reversals(tenant, order_id, reversal_id, payment_id, amount_cents) VALUES(?,?,?,?,?)",
                (tenant, order_id, reversal_id, payment_id, amount_cents),
            )
            conn.execute(
                "UPDATE orders SET paid_cents = paid_cents - ?, status = 'accepted' WHERE tenant=? AND order_id=?",
                (amount_cents, tenant, order_id),
            )
            conn.execute("COMMIT")
        except sqlite3.IntegrityError:
            # 并发下唯一索引兜底（收款已被冲正 / 冲正标识已占用），整笔回滚
            conn.execute("ROLLBACK")
            clash = connect()
            try:
                same_id = clash.execute(
                    "SELECT payment_id FROM reversals WHERE tenant=? AND order_id=? AND reversal_id=?",
                    (tenant, order_id, reversal_id),
                ).fetchone()
            finally:
                clash.close()
            if same_id is not None and same_id["payment_id"] != payment_id:
                raise ReversalConflict("reversal id already used for another payment")
            raise PaymentAlreadyReversed("payment already reversed")
    finally:
        conn.close()

    conn2 = connect()
    try:
        saved = conn2.execute(
            "SELECT reversal_id, payment_id, amount_cents FROM reversals WHERE tenant=? AND order_id=? AND reversal_id=?",
            (tenant, order_id, reversal_id),
        ).fetchone()
        return _reversal_view(tenant, order_id, saved)
    finally:
        conn2.close()

def _reversal_view(tenant: str, order_id: str, reversal_row: sqlite3.Row) -> dict:
    order = get(tenant, order_id)
    return {
        **order,
        "reversal_id": reversal_row["reversal_id"],
        "payment_id": reversal_row["payment_id"],
        "reversed_amount_cents": reversal_row["amount_cents"],
    }

